import sys

class Marks:
    def enterMarks(self, marks):
        self.marks = marks

class Attendance:
    def enterAttendance(self, attendance):
        self.attendance = attendance

class Student(Marks, Attendance):
    def checkResult(self):
        if self.marks >= 40 and self.attendance >= 75:
            print("Result: Pass")
        else:
            print("Result: Fail")

def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 2:
        return
    marks = int(data[0])
    attendance = int(data[1])
    s = Student()
    s.enterMarks(marks)
    s.enterAttendance(attendance)
    s.checkResult()

if __name__ == "__main__":
    main()
